package com.pricetrack.exchange.custody.proof;

import static com.pricetrack.exchange.custody.proof.CTransactionProofModels.*;
import static com.pricetrack.exchange.custody.proof.CTransactionProofVerifierTest.*;
import static org.junit.jupiter.api.Assertions.*;
import com.pricetrack.exchange.custody.abi.*;
import com.pricetrack.exchange.custody.model.CCustodyModels;
import java.math.BigInteger;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.*;
import org.web3j.rlp.*;

/** Public 17/23/29 fixture keys; times are OFFLINE values, never actual elapsed wall-clock seconds. */
class CTransactionRiskProofVerifierTest {
    final CTransactionProofVerifierTest f=new CTransactionProofVerifierTest();
    final CTransactionProofVerifier verifier=new CTransactionProofVerifier();
    final CEip712Verifier crypto=new CEip712Verifier();final CAbiCodec abi=new CAbiCodec();final CAbiEventCodec codec=new CAbiEventCodec();
    CTransactionProofVerifierTest.Seed base(boolean shortSide){var s=f.opened(2000);return new CTransactionProofVerifierTest.Seed(s.vault(),s.token(),change(s.position(),"side",n(shortSide?1:0)));}
    BigInteger adverse(boolean shortSide){return n(shortSide?11_000_000_000L:9_000_000_000L);}
    BigInteger crash(boolean shortSide){return n(shortSide?12_000_000_000L:8_000_000_000L);}
    Result ok(Input i){Result r=verifier.verify(i);assertEquals(Decision.VERIFIED_IN_SCOPE,r.decision(),r.reason());return r;}
    void deny(Input i){Result r=verifier.verify(i);assertNotEquals(Decision.VERIFIED_IN_SCOPE,r.decision());assertNull(r.verified());}
    Input fixture(CTransactionProofVerifierTest.Seed s,CAbiModels.RiskAction action,BigInteger price,long now){
        var p=s.position();String op=h(200+s.vault().lastTransactionIndex());int code=CRulesTransitionModels.Action.valueOf(action.name()).ordinal();
        var r=new CAbiModels.Report(op,POS,ACCOUNT,SYMBOL,n(code),p.version(),p.callEpoch(),p.side(),p.leverage(),p.quantity(),p.entryPriceE8(),p.collateral(),p.collateral(),price,n(now),n(now+30),POLICY,CONTROLLER);
        var ri=new CRulesTransitionModels.Input(CRulesTransitionModels.Action.valueOf(action.name()),r,new CRulesTransitionModels.Terms(CONTROLLER,SYMBOL,POLICY),p,n(now),false,POS,new CRulesTransitionModels.PrestateKeys(POS,ACCOUNT,op));
        var transition=new CRulesTransitionVerifier().verify(ri);List<CAbiEventModels.Log> logs=new ArrayList<>();
        logs.add(codec.encode(RULES,transition.operationApplied()));logs.add(codec.encode(RULES,transition.reportConsumed()));
        if(action==CAbiModels.RiskAction.LIQUIDATE)logs.add(codec.encode(VAULT,new CAbiEventModels.PositionSettled(op,POS,OWNER,p.collateral(),transition.mark().realized(),transition.mark().badDebt(),n(0),n(0))));
        String digest=crypto.reportDigest(r,n(31337),RULES);logs.add(codec.encode(CONTROLLER,new CAbiEventModels.CRiskExecuted(op,POS,OWNER,digest,n(code))));
        var call=new CAbiModels.Risk(action,r,f.sign(digest,ORACLE));var e=f.envelope(call,true,s.vault().lastTransactionIndex()+1,logs);
        e=change(e,"block",change(e.block(),"timestamp",n(now)));
        var point=new CAuthorizationModels.ObservationPoint(e.receipt().blockNumber(),e.receipt().blockHash(),e.receipt().transactionHash(),e.receipt().transactionIndex());
        // Risk intentionally has no nonce key/value and no owner-code assertion.
        var pre=new CAuthorizationModels.Prestate(point,null,null,POS,OWNER,POS,p);
        return new Input(e,new Context(point,SYMBOL,pre,null,ri.prestateKeys(),false,POS,s.vault(),s.token(),h(100)));
    }
    CTransactionProofVerifierTest.Seed called(boolean shortSide){return called(base(shortSide),shortSide);}
    CTransactionProofVerifierTest.Seed called(CTransactionProofVerifierTest.Seed s,boolean shortSide){var r=ok(fixture(s,CAbiModels.RiskAction.START_CALL,adverse(shortSide),1000));return new CTransactionProofVerifierTest.Seed(r.verified().vault(),r.verified().token(),r.verified().rules().after());}
    CAbiModels.Risk call(Input i){return (CAbiModels.Risk)abi.decode(CAbiModels.Target.CONTROLLER,new CSignedTransactionVerifier().verify(i.envelope().rawSignedTransaction(),i.envelope().expectedTransactionHash(),n(31337)).calldata());}
    Input rebuild(Input i,CAbiModels.Risk call,ECKeyPair rawKey){
        byte[] raw=raw(abi.encode(call),rawKey);String hash=hex(Hash.sha3(raw));var old=i.envelope().receipt();List<CReceiptEnvelopeModels.RawLog> logs=old.logs().stream().map(l->change(l,"transactionHash",hash)).toList();
        var receipt=change(change(change(old,"transactionHash",hash),"from",addr(rawKey)),"logs",logs);
        var e=change(change(change(i.envelope(),"rawSignedTransaction",hex(raw)),"expectedTransactionHash",hash),"receipt",receipt);
        var point=change(i.context().point(),"transactionHash",hash);var c=change(change(i.context(),"point",point),"authorizationPrestate",change(i.context().authorizationPrestate(),"point",point));return new Input(e,c);
    }
    Input report(Input i,String field,Object value){var c=call(i);var r=change(c.report(),field,value);return rebuild(i,new CAbiModels.Risk(c.action(),r,f.sign(crypto.reportDigest(r,n(31337),RULES),ORACLE)),RELAY);}
    Input event(Input i,int at,CAbiEventModels.Event e){return f.event(i,at,e);}
    Input context(Input i,String field,Object value){return f.context(i,field,value);}
    byte[] raw(String data,ECKeyPair key){List<RlpType> v=new ArrayList<>(List.of(r(n(7)),r(n(1)),r(n(1_000_000)),RlpString.create(bytes(CONTROLLER)),r(n(0)),RlpString.create(bytes(data))));var unsigned=new ArrayList<>(v);unsigned.addAll(List.of(r(n(31337)),r(n(0)),r(n(0))));var sig=Sign.signMessage(Hash.sha3(RlpEncoder.encode(new RlpList(unsigned))),key,false);v.add(r(n(31337*2L+35+sig.getV()[0]-27)));v.add(r(new BigInteger(1,sig.getR())));v.add(r(new BigInteger(1,sig.getS())));return RlpEncoder.encode(new RlpList(v));}

    @Test void longStartCreatesExactlySixtySecondGraceWithoutConsumingUserNonce(){var s=base(false);var r=ok(fixture(s,CAbiModels.RiskAction.START_CALL,adverse(false),1000));assertEquals(n(1060),r.verified().rules().after().deadline());assertEquals(n(2),r.verified().rules().after().version());assertEquals(s.vault().nonces(),r.verified().vault().nonces());assertEquals(3,r.verified().vault().observations().get(new CCustodyModels.TxKey(h(101),r.verified().token().observations().values().stream().filter(t->t.index().equals(n(4))).findFirst().orElseThrow().hash())).logs().size());}
    @Test void shortStartUsesShortRiskMath(){var r=ok(fixture(base(true),CAbiModels.RiskAction.START_CALL,adverse(true),1000));assertEquals(n(-1000),r.verified().rules().mark().unrealized());assertEquals(n(550),r.verified().rules().mark().maintenance());}
    @Test void longClearRecoversBeforeDeadlineAndKeepsEpoch(){var r=ok(fixture(called(false),CAbiModels.RiskAction.CLEAR_CALL,PRICE,1001));assertEquals(CRulesTransitionModels.Status.ACTIVE,r.verified().rules().after().status());assertEquals(n(0),r.verified().rules().after().deadline());assertEquals(n(1),r.verified().rules().after().callEpoch());}
    @Test void shortClearRecoversWithoutVaultMovement(){var s=called(true);var r=ok(fixture(s,CAbiModels.RiskAction.CLEAR_CALL,PRICE,1001));assertEquals(s.vault().totalFree(),r.verified().vault().totalFree());assertEquals(s.vault().totalLocked(),r.verified().vault().totalLocked());assertEquals(s.vault().house(),r.verified().vault().house());}
    @Test void longLiquidationAtSixtyCapsLossAndBadDebtIsNotCash(){var r=ok(fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060));assertEquals(n(-2000),r.verified().rules().mark().unrealized());assertEquals(n(-1000),r.verified().rules().mark().realized());assertEquals(n(1000),r.verified().rules().mark().badDebt());assertEquals(n(3000),r.verified().vault().house());assertEquals(n(5000),r.verified().vault().actualAssets());}
    @Test void shortLiquidationKeepsHistoricalRulesCollateralAndZeroVaultLock(){var r=ok(fixture(called(true),CAbiModels.RiskAction.LIQUIDATE,crash(true),1060));assertEquals(n(1000),r.verified().rules().after().collateral());assertEquals(n(0),r.verified().vault().positions().get(POS).collateral());assertEquals(CRulesTransitionModels.Status.LIQUIDATED,r.verified().rules().after().status());assertEquals(ZH,r.verified().rules().activePositionForAccount());}
    @Test void fiftyNineSecondsIsRejectedEvenWithFreshReport(){Input i=fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060);deny(change(i,"envelope",change(i.envelope(),"block",change(i.envelope().block(),"timestamp",n(1059)))));}
    @Test void liquidationObservationMustReachDeadlineAndNotFuture(){Input i=fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060);deny(report(report(i,"observedAt",n(1059)),"validUntil",n(1089)));deny(report(report(i,"observedAt",n(1061)),"validUntil",n(1091)));}
    @Test void reportTtlThirtyAndFutureTwoAreEnforced(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(report(i,"validUntil",n(1031)));deny(change(i,"envelope",change(i.envelope(),"block",change(i.envelope().block(),"timestamp",n(1031)))));deny(report(report(i,"observedAt",n(1003)),"validUntil",n(1033)));}
    @Test void recoveredPositionCannotBeLiquidatedAndRiskyPositionCannotClear(){Input liq=fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060);deny(report(liq,"priceE8",PRICE));Input clear=fixture(called(false),CAbiModels.RiskAction.CLEAR_CALL,PRICE,1001);deny(report(clear,"priceE8",crash(false)));}
    @Test void healthyPositionCannotStartMarginCall(){deny(report(fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000),"priceE8",PRICE));}
    @Test void fixedRelayerOnlyNotUserOrOracle(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);assertEquals("C_TX_RISK_CALLER",verifier.verify(rebuild(i,call(i),USER)).reason());assertEquals("C_TX_RISK_CALLER",verifier.verify(rebuild(i,call(i),ORACLE)).reason());}
    @Test void validRawDoesNotMakeWrongOracleSignatureAuthorized(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);var c=call(i);for(ECKeyPair wrong:List.of(USER,RELAY))deny(rebuild(i,new CAbiModels.Risk(c.action(),c.report(),f.sign(crypto.reportDigest(c.report(),n(31337),RULES),wrong)),RELAY));deny(rebuild(i,new CAbiModels.Risk(c.action(),c.report(),"0x"+"00".repeat(65)),RELAY));}
    @Test void reportMustUseExactRulesAndChainDomain(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);var c=call(i);deny(rebuild(i,new CAbiModels.Risk(c.action(),c.report(),f.sign(crypto.reportDigest(c.report(),n(31338),RULES),ORACLE)),RELAY));deny(rebuild(i,new CAbiModels.Risk(c.action(),c.report(),f.sign(crypto.reportDigest(c.report(),n(31337),CONTROLLER),ORACLE)),RELAY));}
    @Test void executorSymbolPolicyAndActionCannotBeChanged(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(report(i,"executor",a(88)));deny(report(i,"symbolHash",h(88)));deny(report(i,"policyHash",h(88)));deny(report(i,"action",n(4)));}
    @Test void missingOwnerOrFullPrestateIsInsufficient(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);for(String field:List.of("authorizationPrestate","rulesKeys","operationUsed","activePosition"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,field,null)).decision());for(String field:List.of("positionOwner","point","positionOwnerKey","rulesPositionKey","rulesPosition"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"authorizationPrestate",change(i.context().authorizationPrestate(),field,null))).decision());}
    @Test void wrongPrestatePointOrMappingKeyCannotBeUsed(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(context(i,"authorizationPrestate",change(i.context().authorizationPrestate(),"point",change(i.context().point(),"transactionHash",h(99)))));deny(context(i,"rulesKeys",change(i.context().rulesKeys(),"positionId",h(99))));deny(context(i,"authorizationPrestate",change(i.context().authorizationPrestate(),"positionOwnerKey",h(99))));}
    @Test void ownerAndAccountRefAreLinkedToActualProjectedPosition(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(context(i,"authorizationPrestate",change(i.context().authorizationPrestate(),"positionOwner",addr(ORACLE))));deny(report(i,"accountRef",h(99)));}
    @Test void fullRulesVersionCollateralAndQuantityCannotConflict(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);for(String field:List.of("version","collateral","quantity","entryPriceE8","callEpoch","deadline")){var p=i.context().authorizationPrestate().rulesPosition();BigInteger value=(BigInteger)field(p,field);deny(context(i,"authorizationPrestate",change(i.context().authorizationPrestate(),"rulesPosition",change(p,field,value.add(n(1))))));}}
    @Test void usedOperationAndActivePointerAreMandatoryAccurateAssertions(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(context(i,"operationUsed",true));deny(context(i,"activePosition",ZH));}
    @Test void userNonceCancellationDoesNotBlockRiskOrConsumeAnotherNonce(){var s=base(false);s=f.stage(s,new CCustodyModels.CancelCall(OWNER,n(1)),OWNER,CONTROLLER,List.of(CONTROLLER),List.of(new CCustodyModels.NonceCancelled(OWNER,n(1))),List.of());var r=ok(fixture(s,CAbiModels.RiskAction.START_CALL,adverse(false),1000));assertEquals(n(2),r.verified().vault().nonces().get(OWNER));assertNull(r.verified().authorization());}
    @Test void ownerCodeAndUserNonceAssertionAreNotRiskAuthorizationConditions(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);i=context(i,"ownerCode",new CAuthorizationModels.CodeObservation(i.context().point(),OWNER,"0x6000"));i=context(i,"authorizationPrestate",change(change(i.context().authorizationPrestate(),"nonceOwnerKey",addr(ORACLE)),"userNonce",n(999)));ok(i);}
    @Test void allFullOperationEventFieldsAreCompared(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);var l=i.envelope().receipt().logs().getFirst();var e=(CAbiEventModels.OperationApplied)codec.decode(CAbiEventModels.EmitterKind.RULES,new CAbiEventModels.Log(RULES,l.topics(),l.data()));for(var field:e.getClass().getRecordComponents()){Object value=field(e,field.getName());deny(event(i,0,change(e,field.getName(),value instanceof BigInteger b?b.add(n(1)):h(99))));}}
    @Test void everyRiskExecutedFieldIsCompared(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);int at=i.envelope().receipt().logs().size()-1;var l=i.envelope().receipt().logs().get(at);var e=(CAbiEventModels.CRiskExecuted)codec.decode(CAbiEventModels.EmitterKind.CONTROLLER,new CAbiEventModels.Log(CONTROLLER,l.topics(),l.data()));for(var field:e.getClass().getRecordComponents()){Object value=field(e,field.getName());deny(event(i,at,change(e,field.getName(),value instanceof BigInteger b?b.add(n(1)):field.getName().equals("owner")?addr(ORACLE):h(99))));}}
    @Test void consumedTimesAndSettlementBadDebtCannotBeInvented(){Input i=fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060);var c=call(i);deny(event(i,1,new CAbiEventModels.FuturesReportConsumed(c.report().operationId(),n(1061),n(1091))));deny(event(i,2,new CAbiEventModels.PositionSettled(c.report().operationId(),POS,OWNER,n(1000),n(-1000),n(1001),n(0),n(0))));}
    @Test void riskPrefixOrderEmitterCountAndExtraTokenEventFail(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);deny(f.log(i,0,"emitter",VAULT));deny(event(i,1,new CAbiEventModels.Transfer(OWNER,VAULT,n(0))));var logs=new ArrayList<>(i.envelope().receipt().logs());Collections.swap(logs,0,1);deny(change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"logs",logs))));}
    @Test void syntacticallyValidExtraTokenEventIsRejectedByRiskFinancialSequence(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);var logs=new ArrayList<>(i.envelope().receipt().logs());var last=logs.removeLast();var token=codec.encode(TOKEN,new CAbiEventModels.Transfer(OWNER,VAULT,n(0)));logs.add(change(change(change(last,"emitter",TOKEN),"topics",token.topics()),"data",token.data()));logs.add(change(last,"logIndex",last.logIndex().add(n(1))));i=change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"logs",logs)));assertEquals("C_TX_RISK_MIDDLE_SCOPE",verifier.verify(i).reason());deny(i);}
    @Test void lossReplenishesHouseButNeverPaysExistingClaims(){var s=called(f.waitingClaimWithHouse(),false);var r=ok(fixture(s,CAbiModels.RiskAction.LIQUIDATE,crash(false),1060));assertEquals(n(1100),r.verified().vault().house());assertEquals(n(950),r.verified().vault().totalUnpaid());assertEquals(s.vault().claims(),r.verified().vault().claims());}
    @Test void topUpRecoveryDoesNotPreventLaterNewCallEpoch(){var s=called(false);var top=f.ok(f.fixture(s,1,adverse(false),1500,false));var recovered=new CTransactionProofVerifierTest.Seed(top.verified().vault(),top.verified().token(),top.verified().rules().after());var r=ok(fixture(recovered,CAbiModels.RiskAction.START_CALL,crash(false),1001));assertEquals(n(2),r.verified().rules().after().callEpoch());assertEquals(n(4),r.verified().rules().after().version());assertEquals(n(1061),r.verified().rules().after().deadline());}
    @Test void revertedRiskRecordsOnlyNoEffectObservationEvenForWrongCaller(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);i=rebuild(i,call(i),USER);i=change(i,"envelope",change(i.envelope(),"receipt",change(change(i.envelope().receipt(),"status",0),"logs",List.of())));var before=i.context().vault();var r=ok(i);assertTrue(r.verified().reverted());assertNull(r.verified().rules());assertNull(r.verified().authorization());assertEquals(before.positions(),r.verified().vault().positions());assertEquals(before.balances(),r.verified().vault().balances());}
    @Test void forgedTokenSeedCannotYieldOnlyOneSuccessfulProjection(){Input i=fixture(base(false),CAbiModels.RiskAction.START_CALL,adverse(false),1000);var balances=new HashMap<>(i.context().token().balances());balances.put(OWNER,balances.get(OWNER).subtract(n(1)));balances.put(a(88),n(1));deny(context(i,"token",change(i.context().token(),"balances",balances)));assertEquals(CCustodyModels.Status.ACTIVE,i.context().vault().positions().get(POS).status());}
    @Test void originalInputReplayIsDeterministicAndOutputScopeRemainsLimited(){Input i=fixture(called(false),CAbiModels.RiskAction.LIQUIDATE,crash(false),1060);var a=ok(i);assertEquals(a,ok(i));assertFalse(a.completeCoverage());assertTrue(a.verificationScope().contains("PREVALIDATED_CONTEXT_ONLY"));assertEquals(n(1000),i.context().vault().totalLocked());assertEquals(n(5000),i.context().token().balanceOf(VAULT));}
}
